{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "summary_card",
        "q1_sales_h2",
        "chart_intro_text",
        "monthly_revenue_table_title",
        "monthly_revenue_table",
        "performance_h2",
        "insights_card",
        "actions_h2",
        "actions_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Monthly Revenue Summary (Q1)",
        "variant": "h1"
      },
      "children": []
    },
    "summary_card": {
      "type": "Card",
      "props": {},
      "children": [
        "summary_stack"
      ]
    },
    "summary_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "total_revenue_text",
        "avg_revenue_text"
      ]
    },
    "total_revenue_text": {
      "type": "Text",
      "props": {
        "text": "Total Revenue (Q1): $49,500"
      },
      "children": []
    },
    "avg_revenue_text": {
      "type": "Text",
      "props": {
        "text": "Average Monthly Revenue: $16,500"
      },
      "children": []
    },
    "q1_sales_h2": {
      "type": "Text",
      "props": {
        "text": "Q1 Sales Performance by Month",
        "variant": "h2"
      },
      "children": []
    },
    "chart_intro_text": {
      "type": "Text",
      "props": {
        "text": "This data can be used to generate a bar chart illustrating monthly revenue trends."
      },
      "children": []
    },
    "monthly_revenue_table_title": {
      "type": "Text",
      "props": {
        "text": "Monthly Revenue (Q1)",
        "variant": "h3"
      },
      "children": []
    },
    "monthly_revenue_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "month",
            "label": "Month"
          },
          {
            "key": "revenue",
            "label": "Revenue ($)"
          }
        ],
        "rows": [
          {
            "month": "Jan",
            "revenue": 15000
          },
          {
            "month": "Feb",
            "revenue": 18000
          },
          {
            "month": "Mar",
            "revenue": 16500
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "performance_h2": {
      "type": "Text",
      "props": {
        "text": "Performance Insights",
        "variant": "h2"
      },
      "children": []
    },
    "insights_card": {
      "type": "Card",
      "props": {},
      "children": [
        "insights_stack"
      ]
    },
    "insights_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "insight1_text",
        "insight2_text"
      ]
    },
    "insight1_text": {
      "type": "Text",
      "props": {
        "text": "February was the highest-performing month with $18,000 in revenue."
      },
      "children": []
    },
    "insight2_text": {
      "type": "Text",
      "props": {
        "text": "Revenue showed growth from January to February, followed by a slight decrease in March."
      },
      "children": []
    },
    "actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "view_financials_button",
        "export_data_button"
      ]
    },
    "view_financials_button": {
      "type": "Button",
      "props": {
        "label": "View Q1 Financials"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/q1-financials"
          }
        }
      }
    },
    "export_data_button": {
      "type": "Button",
      "props": {
        "label": "Export Sales Data"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/export-sales-data"
          }
        }
      }
    }
  }
}
